20	  std::complex<double> Vcc, Fcc, Vsc, Fsc, l12, l23, A5lom;
21	  double s123;
22	
23	  auto zab2 = [&za, &zb](int i1, int i2, int i3, int i4) { 
24	      return za(i1,i2)*zb(i2,i4) + za(i1,i3)*zb(i3,i4); 
25	  };
26	
27	  s123 = s(j1, j2) + s(j2, j3) + s(j3, j1);
28	  A5lom = -za(j3, j4) * zab2(j3,j1,j2,j5) / (za(j1, j2) * za(j2, j3) * s123);
29	
30	  l12 = lnrat(musq, -s(j1, j2));
31	  l23 = lnrat(musq, -s(j2, j3));
32	  Vcc = -(epinv*epinv2 + epinv*l12 + half*std::pow(l12, 2))
33	      -(epinv*epinv2 + epinv*l23 + half*std::pow(l23, 2))
34	      - two * (epinv + l23) - four;
35	
36	  Fcc = zab2(j3,j1,j2,j5) / (za(j1, j2) * za(j2, j3) * s123) *
37	      (za(j3, j4) * Lsm1(-s(j1, j2), -s123, -s(j2,j3), -s123)
38	      + two * za(j3, j1) * zab2(j4,j2,j3,j1) * L0(-s(j2, j3), -s123) / s123);
39	
40	  Vsc = half * (epinv + l23) + one;
41	  Fsc = -za(j3, j4) * za(j3, j1) * zb(j1, j5) / (za(j1,j2) * za(j2, j3)) * L0(-s(j2, j3), -s123) / s123
42	      + half * std::pow(za(j3, j1), 2) * zb(j1, j5) * zab2(j4,j2,j3,j1) / 
43	      (za(j1, j2) * za(j2,j3)) * L1(-s(j2, j3), -s123) / std::pow(s123, 2);
44	
45	  return (Vcc + Vsc) * A5lom + Fcc + Fsc;
46	}
