#ifndef ATREE_HPP
#define ATREE_HPP

#include <FArray.hpp>
#include <complex>
#include <string>

// C++ entry point: amplitude for q-(p4)+Q(-p2)+l-(-p5) --> q+(p1)+Q-(p3)+l+(p6)
// st selects the helicity configuration: "pp", "pm", or "sl"
extern std::complex<double> atree(const std::string& st,
                                   int j1, int j2, int j3, int j4, int j5, int j6,
                                   FArray2D<std::complex<double>>& za,
                                   FArray2D<std::complex<double>>& zb);

extern "C" {
  // Wrapper called from the Fortran shim atree_fi.f90.
  // The two-character string st is split into individual characters st1, st2
  // to cross the Fortran/C boundary cleanly via bind(C).
  extern std::complex<double> atree_wrapper(char st1, char st2,
                                             int j1, int j2, int j3, int j4, int j5, int j6,
                                             std::complex<double>* fza,
                                             std::complex<double>* fzb);
}

#endif

//  SPDX-License-Identifier: GPL-3.0-or-later
//  Copyright (C) 2019-2022, respective authors of MCFM.
//
//  Translated from W2jet/atree.f (R.K. Ellis, July 1998).
//  Implements BDKW Eq.(3.10): basic tree amplitude for
//  q-(p4)+Q(-p2)+l-(-p5) --> q+(p1)+Q-(p3)+l+(p6)
//  All outgoing particles are right-handed, except Q(p3) which is left-handed.
//  Note: all tree amplitudes are divided by i relative to the BDKW paper.

#include "atree.hpp"
#include <W1jet.hpp>
#include <FArray.hpp>
#include <complex>
#include <mxpart_mod.hpp>
#include <sprods_com_mod.hpp>
#include <string>

using namespace mxpart_mod;
using namespace sprods_com_mod;

std::complex<double> atree(const std::string& st,
                            int j1, int j2, int j3, int j4, int j5, int j6,
                            FArray2D<std::complex<double>>& za,
                            FArray2D<std::complex<double>>& zb) {

  // Statement function 'tree' translated to a C++ lambda.
  // Implements BDKW Eq.(3.10) for the pp (all-right-handed) configuration;
  // pm and sl are obtained by crossing via the caller below.
  // t(i1,i2,i3) = s(i1,i2)+s(i2,i3)+s(i1,i3) from W1jet.
  auto tree = [&](int i1, int i2, int i3, int i4, int i5, int i6) -> std::complex<double> {
    return
        +zb(i1,i2)*za(i5,i4)*(za(i3,i1)*zb(i1,i6)+za(i3,i2)*zb(i2,i6))
        / (s(i2,i3)*s(i5,i6)*t(i1,i2,i3))  // @coverage-probe
        +za(i3,i4)*zb(i6,i1)*(za(i5,i3)*zb(i3,i2)+za(i5,i4)*zb(i4,i2))
        / (s(i2,i3)*s(i5,i6)*t(i2,i3,i4));
  };

  std::complex<double> result;
  if (st == "pp") {
    result = +tree(j1,j2,j3,j4,j5,j6);
  } else if (st == "pm") {
    result = -tree(j1,j3,j2,j4,j5,j6);
  } else if (st == "sl") {
    // not a real tree amplitude, but an auxiliary quantity
    result = -tree(j3,j1,j2,j4,j5,j6);
  }
  return result;
}

extern "C" {
  // Called from atree_fi.f90.  The two-character Fortran string is passed
  // as two individual characters (st1, st2) to satisfy bind(C) requirements.
  std::complex<double> atree_wrapper(char st1, char st2,
                                      int j1, int j2, int j3, int j4, int j5, int j6,
                                      std::complex<double>* fza,
                                      std::complex<double>* fzb) {
    char st_arr[3] = {st1, st2, '\0'};
    std::string st(st_arr, 2);
    FArray2D<std::complex<double>> za(fza, mxpart, mxpart);
    FArray2D<std::complex<double>> zb(fzb, mxpart, mxpart);
    return atree(st, j1, j2, j3, j4, j5, j6, za, zb);
  }
}

